def step_pose(s: Session, pos, quat, settle=0):
    q, ok, err = s.ik(pos, quat)
    if not ok:
        raise RuntimeError(f'IK failed: {err:.5f} m at {np.asarray(pos).round(5).tolist()}')
    s.step(q)
    for _ in range(settle):
        s.step(q)


def move_pose(s: Session, pos, quat, speed=0.035, settle=3):
    p0, q0 = s.tip_pose()
    pos = np.asarray(pos, dtype=np.float64)
    dist = float(np.linalg.norm(pos - p0))
    qdot = min(1.0, max(-1.0, abs(float(np.dot(q0 / np.linalg.norm(q0), quat / np.linalg.norm(quat))))) )
    angle = 2 * math.acos(qdot)
    n = max(1, int(math.ceil(dist / (speed / 20.0))), int(math.ceil(angle / 0.08)))
    fails = 0
    for k in range(1, n + 1):
        t = k / n
        p = p0 + t * (pos - p0)
        q = quat_slerp(q0, quat, t)
        qj, ok, err = s.ik(p, q)
        if ok:
            s.step(qj)
        else:
            fails += 1
            if err > 0.003:
                raise RuntimeError(f'move IK failed ({err:.4f} m) at {p.round(5)}')
            s.step(qj)
    for _ in range(settle):
        s.step(s.hold_action())
    return {'steps': n + settle, 'ik_failures': fails}


def draw_path(s: Session, route, index: int):
    quat_list = [s.tip_down_quat(float(yaw)) for yaw in route['yaw']]
    p = px_to_world(s, route['path_px'], CONTACT_Z)
    failures = 0
    for pos, quat in zip(p, quat_list):
        q, ok, err = s.ik(pos, quat)
        if not ok:
            failures += 1
            if err > 0.0025:
                raise RuntimeError(f'path IK failed on stroke {index}: {err:.4f} m')
        s.step(q)
    # Let the commanded endpoint settle before lifting.
    for _ in range(8):
        s.step(s.hold_action())
    actual_p, _ = s.tip_pose()
    return {'path_samples': len(p), 'ik_failures': failures,
            'path_px_len': float(np.linalg.norm(np.diff(route['path_px'], axis=0), axis=1).sum()),
            'end_error_mm': 1000 * float(np.linalg.norm(actual_p - p[-1]))}


def main():
    OUT.mkdir(parents=True, exist_ok=True)
    s = Session(instance=INSTANCE)
    s.reset()
    routes = glyph_routes(s.target_image())
    s.record_start()
    p = s.primitives()

    # One ink dip; ink remains loaded for the entire lettering pass.
    q0 = s.tip_down_quat(0.0)
    move_pose(s, [-0.100, 0.150, 0.043], q0, speed=0.05, settle=2)
    move_pose(s, [-0.100, 0.150, 0.027], q0, speed=0.010, settle=8)

